CHECKS = {'==': lambda a, b: a == b, '>=': lambda a, b: a >= b, '<': lambda a, b: a < b}

def satisfies(installed, op, wanted):
    return CHECKS[op](as_tuple(installed), as_tuple(wanted))

print(satisfies('3.0.3', '>=', '3.0'))
print(satisfies('1.1.1', '>=', '3.0'))
