def as_tuple(v):
    return tuple(int(p) for p in v.split('.'))

def compatible(installed, wanted):
    i, w = as_tuple(installed), as_tuple(wanted)
    return i >= w and i[:len(w) - 1] == w[:-1]

for v in ['2.31.0', '2.32.3', '3.0.0', '2.30.9']:
    print(v, compatible(v, '2.31'))

